// mla fork of original by @neozhaoliang, but going for a more 19th Century aesthetic.
// Same zoom & pan controls as before (except pan setting preserved over window resize).

// Getting everything to scale properly when zooming is a nuisance, but this seems
// to work OK.

// Original header //
/*
Reproduce an image by Fricke and Klein over a century ago.

"Vorlesungen uber die Theorie der automorphen Funktionen,
 Teubner Leipzig, Germany, 1897."

The coloring and circle parameters are taken from

https://images-archive.math.cnrs.fr/Un-ensemble-limite.html?lang=fr

1. Use mouse to pan
2. Press W/S to zoom in/out

*/

#define PI 3.141592653589793
#define MAX_ITER 7
#define CURVE_THICKNESS 3e-3
#define AA 2

float zoom;

bool Equal(vec3 z, vec2 a) {
    float k = (1. + length(a)) / (1. + length(z.xy));
    return length(z.xy - a) / (zoom*z.z) < CURVE_THICKNESS * k;
}


const vec2 z2 = vec2(0.068, -0.272);
const vec2 z3 = vec2(0.426, -0.672);
const vec2 z4 = vec2(0.816, 0.362);
const vec2 z5 = vec2(-1.154, 0.854);
const float r1 = 0.4;

const float d23 = length(z3 - z2);
const float d34 = length(z3 - z4);
const float d24 = length(z4 - z2);
const float d45 = length(z4 - z5);

const float r2 = (d23 + d24 - d34) / 2.0;
const float r3 = (d23 + d34 - d24) / 2.0;
const float r4 = (d24 + d34 - d23) / 2.0;
const float r5 = d45 - r4;

const float a = r5 + r1;
const float b = r2 + r1;
const float c = length(z2 - z5);

vec2 z1;
vec2 u24, u23, u34, u12, u15, u45;
vec2 zr1;
float rr1;

vec2 circles[5];
float radii[5];

vec3 getColor(vec2 z, vec2 fragCoord) {
    int count = 0;
    vec3 zdz = vec3(z,1);
    int iter = int(float(MAX_ITER)*max(1.0,-log2(zoom)));
    iter += 1-iter%2; // Odd number of iterations
    int index = -1;
    for (int i = 0; i < iter; i++) {
        for (int j = 0; j < 6; j++) {
            vec2 p = vec2[6](u12, u15, u23, u24, u34, u45)[j];
            if (Equal(zdz, p)) return BLACK;
        }
        for (int j = 0; j < 5; j++) {
          vec2 z = circles[j]; 
          float r = radii[j];
          if (length(zdz.xy - z) < r) {
            zdz = invert(zdz, z, r);
            count++;
            index = j;
            break;
          }
        }
    }
    vec3 tex = texture(iChannel1,fragCoord/iResolution.x).xyz;
    float line = 0.5+0.5*dot(tex,tex);
    vec3 color = vec3(1,1,0.6);
    float px = length(fwidth(zdz.xy));
    if (index >= 0) {
      float d = length(zdz.xy-circles[index])-radii[index];
      float scale = zdz.z;
      if (zoom*scale < 1e3) { // Avoid infinite distances!
        color = mix(vec3(0),color,smoothstep(-px,px,d-0.003*zoom*scale*line));
      }
    }
    vec2 p = fragCoord/iResolution.xy;
    float px1 = fwidth(p.y);
    if (count%2 == 0) {
      // Hatching
      float N = 100.0;
      float d = fract(N*(p.y));
      d = min(d,1.0-d);
      d /= N;
      float hwidth = 0.0015*line;
      color = mix(vec3(0.2,0,0),color,smoothstep(-px1,px1,d-hwidth));
    }
    color *= 0.5+0.5*sqrt(tex);
    return color;
}

void init() {
    z1 = findThirdVertex(z2, z5, a, b, c);
    u24 = getTouchPoint(z2, r2, z4);
    u23 = getTouchPoint(z2, r2, z3);
    u34 = getTouchPoint(z3, r3, z4);
    u12 = getTouchPoint(z1, r1, z2);
    u15 = getTouchPoint(z1, r1, z5);
    u45 = getTouchPoint(z4, r4, z5);
    zr1 = circumcenter(u23, u24, u34);
    rr1 = length(u24 - zr1);

    circles[0] = z1;
    circles[1] = z2;
    circles[2] = z3;
    circles[3] = z4;
    circles[4] = z5;
    radii[0] = r1;
    radii[1] = r2;
    radii[2] = r3;
    radii[3] = r4;
    radii[4] = r5;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    init();
    vec4 pan_vals = texelFetch(iChannel0, ivec2(0,0),0);
    pan_vals *= vec4(iResolution.xy,iResolution.xy);
    zoom = texelFetch(iChannel0, ivec2(10,10), 0).x;
    float ylow = -1.0*zoom;
    float yhigh = 1.0*zoom;
    float xleft = -1.0*zoom;
    float xright = 1.0*zoom;
    vec3 col = vec3(0);
    for(int ii=0; ii<AA; ii++) {
    for(int jj=0; jj<AA; jj++) {
        vec2 o = vec2(float(ii), float(jj)) / float(AA);
        vec2 R = (fragCoord  + o - pan_vals.xy * pow(zoom, -1.0)) / iResolution.y;
        R *= 0.8;
        R -= vec2(0.23, -0.1);
        vec2 uv = vec2(xleft+(xright-xleft)*R.x,ylow + (yhigh - ylow)*R.y);

        col += getColor(uv,fragCoord);
    }
    }
    col /= (float(AA) * float(AA));
    col = pow(col,vec3(0.4545));
    fragColor = vec4(col, 1.0);
}

#define L2(x)  dot(x, x)

const vec3 BLACK = vec3(0.0);
const vec3 RED = vec3(1.0, 0.0, 0.0);
const vec3 VIOLET = vec3(0.39, 0.16, 0.71);
const vec3 GREEN = vec3(0.0, 0.5, 0.0);
const vec3 YELLOW = vec3(0.78, 0.78, 0.0);
const vec3 BROWN = vec3(0.75, 0.5, 0.0);
const vec3 LTGREEN = vec3(0.36, 0.88, 0.25);
const vec3 LTVIOLET = vec3(0.78, 0.39, 1.0);


vec2 conj(vec2 z) { 
    return vec2(z.x, -z.y);
}

vec2 cinv(vec2 z) {
    return conj(z) / dot(z, z);
}

vec2 cmul(vec2 z, vec2 w) {
    return vec2(
    z.x * w.x - z.y * w.y,
    z.x * w.y + z.y * w.x
    );
}

vec2 cdiv(vec2 z, vec2 w) {
    return cmul(z, conj(w)) / dot(w, w);
}

vec4 sub(vec4 z_dz, vec2 b) {
    return vec4(z_dz.xy - b, z_dz.zw);
}

vec4 sub(vec2 b, vec4 z_dz) {
    return vec4(b - z_dz.xy, -z_dz.zw);
}

vec4 add(vec4 z_dz, vec2 b) {
    return vec4(z_dz.xy + b, z_dz.zw);
}

vec4 add(vec2 b, vec4 z_dz) {
    return add(z_dz, b);
}

vec4 mul(vec4 z_dz, vec2 b) {
    return vec4(cmul(z_dz.xy, b), cmul(z_dz.zw, b));
}

vec4 mul(vec2 b, vec4 z_dz) {
    return mul(z_dz, b);
}

vec4 conj(vec4 z_dz) {
    return vec4(conj(z_dz.xy), conj(z_dz.zw));
}

vec4 inv(vec4 z_dz) {
    vec2 b = cinv(z_dz.xy);
    return vec4(b, cmul(-z_dz.zw, cmul(b,b)));
}

vec3 invert(vec3 zdz, vec2 cen, float r) {
    // Some simplifications by mla
    vec2 z = zdz.xy-cen;
    float k = r*r/dot(z,z);
    z *= k;
    z += cen;
    return vec3(z,k*zdz.z);
}

vec2 findThirdVertex(vec2 z, vec2 w, float a, float b, float c) {
    vec2 d = z - w;
    d /= length(d);
    float k = (a * a - b * b + c * c) / (2.0 * c);
    float h = sqrt(a * a - k * k);
    return w + vec2(d.x * k + d.y * h, d.y * k - d.x * h);
}

vec2 circumcenter(vec2 A, vec2 B, vec2 C) {
    float dx = B.x - A.x;
    float dy = B.y - A.y;
    float ex = C.x - A.x;
    float ey = C.y - A.y;
    float bl = dx * dx + dy * dy;
    float cl = ex * ex + ey * ey;
    float d = 0.5 / (dx * ey - dy * ex);
    float x = A.x + (ey * bl - dy * cl) * d;
    float y = A.y + (dx * cl - ex * bl) * d;
    return vec2(x, y);
}

vec2 getTouchPoint(vec2 z1, float r1, vec2 z2) {
    vec2 d = z2 - z1;
    d /= length(d);
    return d * r1 + z1;
}

float cross2d(vec2 A, vec2 B, vec2 C) {
    vec2 AB = B - A;
    vec2 AC = C - A;
    return AB.x * AC.y - AB.y * AC.x;
}

// https://www.shadertoy.com/view/ldyGzW
const int Key_A = 65; const int Key_B = 66; const int Key_C = 67; const int Key_D = 68; const int Key_E = 69;
const int Key_F = 70; const int Key_G = 71; const int Key_H = 72; const int Key_I = 73; const int Key_J = 74;
const int Key_K = 75; const int Key_L = 76; const int Key_M = 77; const int Key_N = 78; const int Key_O = 79;
const int Key_P = 80; const int Key_Q = 81; const int Key_R = 82; const int Key_S = 83; const int Key_T = 84;
const int Key_U = 85; const int Key_V = 86; const int Key_W = 87; const int Key_X = 88; const int Key_Y = 89;
const int Key_Z = 90;
const int Key_0 = 48; const int Key_1 = 49; const int Key_2 = 50; const int Key_3 = 51; const int Key_4 = 52;
const int Key_5 = 53; const int Key_6 = 54; const int Key_7 = 55; const int Key_8 = 56; const int Key_9 = 57;
const int Key_Space = 32;

float ReadKeyInternal( int key, bool toggle )
{
	return textureLod( iChannel1, vec2( (float(key)+.5)/256.0, toggle?.75:.25 ), 0.0 ).x;
}

float ReadKey( int key )
{
	return ReadKeyInternal(key,false);
}

float ReadKeyToggle( int key )
{
	return ReadKeyInternal(key,true);
}



//Storage Code For Pan and Zoom


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.0,0.0,0.0,1.0);
    //Only run once each frame

        if (ivec2(fragCoord.xy) == ivec2(0,0) )
        {
            //Mouse Pan Stored In Here

            vec4 mouse = iMouse;
            mouse /= vec4(iResolution.xy,iResolution.xy);
            vec4 prev_info = textureLod(iChannel0, vec2(0.0,0.0),0.0);
            float Zoom = textureLod(iChannel0, vec2(10.5,10.5)/iResolution.xy,0.0).x;
            float prev_pan_x = prev_info.x;
            float prev_pan_y = prev_info.y;

            float legacy_pan_x = prev_info.z;
            float legacy_pan_y = prev_info.w;

            float pan_x = (mouse.x - abs(mouse.z))*Zoom + legacy_pan_x;
            float pan_y = (mouse.y - abs(mouse.w))*Zoom + legacy_pan_y;

            if (mouse.z < 0.0)
            {
                //Mouse has been lifted up
                legacy_pan_x = prev_pan_x;
                legacy_pan_y = prev_pan_y;
                pan_x = legacy_pan_x;
                pan_y = legacy_pan_y;

            }
            fragColor = vec4(pan_x, pan_y, legacy_pan_x, legacy_pan_y);


        }

    //Zoom settings
    if (ivec2(fragCoord.xy) == ivec2(10,10) )
    {

        float x = textureLod(iChannel0, vec2(10.5,10.5)/iResolution.xy,0.0).y;
        //Number of times zoom in - zoom out has happend

        x += ReadKey(Key_W)-ReadKey(Key_S);

        float Zoom = pow(2.71, -x*0.05); //Times all limits by this value

        fragColor = vec4(Zoom, x,0.0,0.0);
    }


}
